function BlockedNotice({ blocked }: { blocked: Blocked }) {
  const suspended = blocked.kind === 'suspended';
  return <div role="alert" className="mb-5.5 rounded-xl border border-[#f0d6cb] bg-[#fff6f2] p-4.5 text-[#7a4a3d]">
    <div className="flex items-center gap-2.5 text-16 font-semibold text-[#a4543f]"><Ban size={19} />{suspended ? 'บัญชีนี้ถูกระงับ' : 'บัญชีนี้ถูกลบโดยผู้ดูแลระบบ'}</div>
    {suspended && <div className="mt-3.5 rounded-lg bg-white/70 px-3.5 py-3"><small className="block text-12 text-[#9a6a5c]">เหตุผลจากผู้ดูแลระบบ</small><p className="mt-1 text-14 leading-[1.7] whitespace-pre-wrap [overflow-wrap:anywhere]">{blocked.reason || 'ไม่ได้ระบุเหตุผล'}</p></div>}
    {blocked.at && <small className="mt-2.5 block text-12 text-[#9a6a5c]">{suspended ? 'ระงับเมื่อ' : 'ลบเมื่อ'} {dateLabel(blocked.at)} {timeLabel(blocked.at)} น.</small>}
    <p className="mt-3 text-13 leading-[1.7]">{suspended ? 'ตอนนี้เข้าสู่ระบบไม่ได้ ข้อมูลของคุณยังถูกเก็บไว้ หากคิดว่าเกิดความผิดพลาด กรุณาติดต่อผู้ดูแลระบบ' : 'ข้อมูลของบัญชีนี้ถูกลบแล้ว หากต้องการใช้งานต่อสามารถสมัครใหม่ หรือติดต่อผู้ดูแลระบบ'}</p>
  </div>;
}
function Auth({ type, onType, onBack, onUser, onDemo, initialBlocked }: { type: 'login' | 'register'; onType: (t: 'login' | 'register') => void; onBack: () => void; onUser: (u: DemoUser) => void | Promise<void>; onDemo: () => void; initialBlocked: Blocked | null }) {
  const [blocked, setBlocked] = useState<Blocked | null>(initialBlocked);
  const [error, setError] = useState(''); const [info, setInfo] = useState(''); const [show, setShow] = useState(false); const [busy, setBusy] = useState(false);
  const pw = cloudMode ? 'รหัสผ่าน' : 'รหัสผ่านจำลอง'; const account = cloudMode ? 'บัญชี' : 'บัญชีจำลอง';
  function fail(e: unknown, fallback: string) { if (e instanceof AccountBlockedError) setBlocked(e.blocked); else setError(e instanceof Error ? e.message : fallback); setBusy(false); }
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setError(''); setInfo(''); setBlocked(null); const form = new FormData(e.currentTarget); const email = String(form.get('email')).trim().toLowerCase(); const password = String(form.get('password')); const name = String(form.get('name') || '').trim();
    if (password.length < 6) { setError(`กรุณาใช้${pw}อย่างน้อย 6 ตัวอักษร`); return; }
    if (cloudMode) {
      if (type === 'register' && !name) { setError('กรุณากรอกชื่อของคุณ'); return; }
      if (type === 'register' && password !== String(form.get('confirm'))) { setError('รหัสผ่านทั้งสองช่องไม่ตรงกัน'); return; }
      setBusy(true);
      try {
        const user = type === 'register' ? await signUp(name, email, password) : await signIn(email, password);
        if (!user) { setBusy(false); onType('login'); setInfo('สมัครสมาชิกแล้ว กรุณายืนยันอีเมลจากลิงก์ที่ส่งไป แล้วเข้าสู่ระบบ'); return; }
        await onUser(user);
      } catch (e) { fail(e, 'เชื่อมต่อ Supabase ไม่ได้'); }
      return;
    }
    try {
      const accounts = readAccounts(); let user: DemoUser | undefined;
      if (type === 'register') {
        if (!name) { setError('กรุณากรอกชื่อของคุณ'); return; }
        if (password !== String(form.get('confirm'))) { setError('รหัสผ่านทั้งสองช่องไม่ตรงกัน'); return; }
        if (accounts.some(a => a.email === email) || email === DEMO_USER.email) { setError('อีเมลนี้มีบัญชีจำลองแล้ว กรุณาเข้าสู่ระบบ'); return; }
        user = registerAccount(name, email);
      } else {
        user = accounts.find(a => a.email.toLowerCase() === email);
        if (!user) { setError('ไม่พบบัญชีจำลองนี้ กรุณาสมัครสมาชิกก่อน หรือเลือกลองใช้เดโม'); return; }
      }
      setBusy(true); onUser(user);
    } catch (e) { fail(e, 'บันทึกบัญชีไม่ได้ กรุณาเปิดใช้งานพื้นที่จัดเก็บของเบราว์เซอร์'); }
  }
  return <div className="grid min-h-screen grid-cols-[42%_58%] bg-white max-md:grid-cols-[36%_64%] max-sm:block">
    <aside className="relative flex flex-col justify-between overflow-hidden bg-forest px-14 py-12 text-[#e6eedb] after:pointer-events-none after:absolute after:-bottom-[260px] after:-left-17.5 after:size-[550px] after:rounded-full after:border after:border-white/5 after:shadow-[0_0_0_70px_#ffffff03,0_0_0_140px_#ffffff02] max-lg:p-9.5 max-md:px-6.5 max-md:py-8.5 max-sm:hidden">
      <Brand variant="auth" />
      <div className="relative z-1 py-12.5"><span className={ui.eyebrow('text-[.66rem] tracking-[1.9px]', 'text-[#68715c]!')}>A FRESH START, EVERY DAY.</span><h1 className="my-6 text-[3.3rem] leading-normal font-medium text-[#f1f3e7] max-lg:text-[2.8rem] max-md:text-[2.4rem]">แผนที่ดี<br />เริ่มต้นจาก<br /><span className="text-[#c5dba1]">พื้นที่ของคุณ</span></h1><p className="text-[.98rem] leading-[1.9] text-[#687064]">โปรเจ็ค งานย่อย และเวลาที่คุณตั้งใจ<br />ทุกอย่างอยู่ด้วยกันที่นี่</p><div className="mt-9.5 flex gap-3.75 border-t border-white/10 pt-6.5 text-[#667351]"><Leaf size={24} /><p className="text-14 leading-[1.9] text-[#687064]">“ไม่ต้องทำทุกอย่างในวันเดียว<br />แค่รู้ว่าวันนี้จะเริ่มจากอะไร”</p></div></div>
      <small className="relative z-1 text-[#61735f]">ProjectRecord · Demo edition</small>
    </aside>
    <main className="flex flex-col justify-between px-15 py-9.5 max-md:px-10 max-md:py-7.5 max-sm:min-h-screen max-sm:p-7">
      <button className={ui.cx(ui.backLink, 'self-start')} onClick={onBack}><ArrowLeft size={16} /> กลับหน้าหลัก</button>
      <div className="mx-auto my-6.25 w-full max-w-[410px] max-sm:mt-8 max-sm:mb-10">
        <span className={ui.eyebrow('text-[.67rem] tracking-[1.9px]')}>YOUR OWN LITTLE WORKSPACE</span><h2 className="mt-2 text-[1.85rem] max-sm:text-[1.8rem]">{type === 'login' ? 'ยินดีต้อนรับกลับมา' : 'เริ่มต้นแผนใหม่ด้วยกัน'}</h2><p className="mt-3 mb-6.75 text-15 text-[#697068]">{type === 'login' ? 'เข้าสู่พื้นที่ทำงาน แล้วไปต่อจากสิ่งที่คุณวางไว้' : cloudMode ? 'สร้างบัญชีสำหรับเก็บโปรเจ็คของคุณ ใช้ได้ทุกอุปกรณ์' : 'สร้างบัญชีจำลองสำหรับเก็บโปรเจ็คของคุณบนเครื่องนี้'}</p>
        {blocked && <BlockedNotice blocked={blocked} />}
        <form onSubmit={submit} key={type}>{type === 'register' && <label>ชื่อของคุณ<input name="name" autoComplete="name" placeholder="เช่น พุฒิ ศรีสุข" required maxLength={80} /></label>}<label>อีเมล<input name="email" type="email" autoComplete="email" placeholder="you@example.com" required /></label><label>{pw}<div className="relative"><input className="pr-12" name="password" type={show ? 'text' : 'password'} autoComplete={cloudMode ? (type === 'login' ? 'current-password' : 'new-password') : 'off'} placeholder="อย่างน้อย 6 ตัวอักษร" minLength={6} required /><button className={ui.iconBtn({ className: 'absolute top-1.5 right-1.75 text-[#687065]' })} type="button" aria-label={show ? 'ซ่อนรหัสผ่าน' : 'แสดงรหัสผ่าน'} onClick={() => setShow(!show)}>{show ? <EyeOff size={18} /> : <Eye size={18} />}</button></div></label>{type === 'register' && <label>ยืนยัน{pw}<input name="confirm" type={show ? 'text' : 'password'} autoComplete={cloudMode ? 'new-password' : 'off'} minLength={6} required placeholder="กรอกรหัสผ่านอีกครั้ง" /></label>}{error && <div className={ui.formError} role="alert">{error}</div>}{info && <div className={ui.formWarning} role="status">{info}</div>}<div className="mt-2 mb-5 flex gap-2.5 rounded-lg bg-[#f5f7f0] p-3 text-13 leading-[1.7] text-[#67715e] [&>svg]:mt-0.75"><Sparkles size={17} /><span>{cloudMode ? 'ยืนยันตัวตนด้วย Supabase Auth สิทธิ์ผู้ใช้งานและแอดมินตรวจที่ฐานข้อมูล ผู้ใช้เห็นเฉพาะข้อมูลของตนเอง' : 'บัญชีนี้เป็นการจำลอง ไม่เก็บรหัสผ่าน และยอมรับรหัสผ่านใดก็ได้ที่ยาว 6 ตัวอักษรขึ้นไปเมื่อเข้าสู่ระบบ โปรดใช้ข้อมูลสมมติ'}</span></div><button className={ui.btn('primary', 'md', 'w-full')} disabled={busy}>{type === 'login' ? 'เข้าสู่ระบบ' : `สร้าง${account}`} <ArrowRight size={17} /></button></form>
        <div className="mt-4.75 text-center text-14 text-[#687064]">{type === 'login' ? 'ยังไม่มีบัญชี?' : 'มีบัญชีอยู่แล้ว?'} <button className="font-semibold text-[#3e6947]" onClick={() => { setError(''); setInfo(''); onType(type === 'login' ? 'register' : 'login'); }}>{type === 'login' ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ'}</button></div>
        {!cloudMode && <><div className="mt-7.5 h-7.5 border-t border-[#e9ece4] text-center"><span className="relative -top-3.25 bg-white px-3 text-13 text-[#6a7065]">หรือเริ่มสำรวจได้เลย</span></div><button className={ui.btn('outline', 'md', 'w-full')} onClick={onDemo}><Play size={16} /> ลองใช้เดโมพร้อมข้อมูลตัวอย่าง</button></>}
      </div>
      <small className="text-center text-[#697062] max-sm:text-12">{cloudMode ? 'ข้อมูลจัดเก็บใน Supabase และแยกตามบัญชีผู้ใช้' : 'ข้อมูลจะอยู่เฉพาะเบราว์เซอร์และเครื่องที่ใช้งาน'}</small>
    </main>
  </div>;
}

function TaskRow({ task, project, onStatus, onEdit, compact = false, readOnly = false }: { task: Task; project?: Project; onStatus: (t: Task, s: Status) => void; onEdit: (t: Task) => void; compact?: boolean; readOnly?: boolean }) {
  const done = task.status === 'done';
  return <div className={ui.cx('task-row flex min-h-20.25 items-center border-t border-[#f0f2ec] px-5.75 py-4.25 max-sm:gap-2.5 max-sm:px-4.75 max-sm:py-4 max-xs:gap-2 max-xs:p-3.75', compact ? 'gap-2.75' : 'gap-3', done && 'completed')}>
    <button className={ui.cx('task-check grid size-5 shrink-0 place-items-center rounded-md border-[1.5px] p-0', done ? 'border-[#819e65] bg-[#819e65] text-white' : 'border-[#d6dfca] hover:border-[#7f9f64] hover:bg-[#f0f5e7]')} disabled={readOnly} title={readOnly ? 'นำโปรเจ็คกลับมาก่อนแก้ไขงาน' : undefined} onClick={() => onStatus(task, task.status === 'done' ? 'todo' : 'done')} aria-label={`${task.status === 'done' ? 'ยกเลิกสถานะเสร็จ' : 'ทำเครื่องหมายเสร็จ'}: ${task.title}`}>{task.status === 'done' && <Check size={16} />}</button>
    <button className="task-copy min-w-0 flex-1 p-0 text-left disabled:cursor-default disabled:opacity-100" disabled={readOnly} onClick={() => onEdit(task)}><strong className={ui.cx('block text-[.9rem] font-medium [overflow-wrap:anywhere] max-sm:text-14 max-xs:text-13', done && 'text-[#6a7065] line-through')}>{task.title}</strong><span className={ui.cx('mt-1.25 flex flex-wrap items-center gap-1.25 text-[#6a7062] max-sm:text-11 max-xs:text-[.65rem]', compact ? 'text-11' : 'text-[.72rem]')}><i className="mr-0.5 block size-1.25 rounded-full" style={{ background: project?.color }} />{project?.name || 'โปรเจ็ค'}{task.start && <><span className="mx-0.5 text-[#6b6f64]">·</span><Clock3 size={12} />{dateLabel(task.start)} {timeLabel(task.start)}{task.end && `–${timeLabel(task.end)}`}</>}</span></button>
    {!compact && <span className={ui.cx('flex w-19 shrink-0 items-center gap-1.25 text-12 max-sm:hidden', PRIORITY_COLOR[task.priority])}><span className="size-1.25 rounded-full bg-current" />{PRIORITY_LABEL[task.priority]}</span>}
    <div className="ml-auto flex flex-col flex-wrap items-end gap-1 text-12 whitespace-nowrap text-[#6b705f] max-sm:text-11">{task.due && !compact && <span className={overdue(task) ? 'text-[#8d684b]' : ''}>{dateLabel(task.due)} <span className="max-sm:hidden">{timeLabel(task.due)}</span></span>}{dueSoon(task) && <Badge kind="due-soon" className="max-xs:px-1.25 max-xs:text-10">ใกล้ส่ง</Badge>}<Badge kind={overdue(task) ? 'late' : task.status} className="max-xs:px-1.25 max-xs:text-10">{overdue(task) ? 'เลยกำหนด' : STATUS_LABEL[task.status]}</Badge></div>
    {!readOnly && !compact && <button className={ui.iconBtn({ className: 'text-[#697060] max-xs:hidden', size: 'h-7 w-6.5' })} aria-label={`แก้ไข ${task.title}`} onClick={() => onEdit(task)}><Pencil size={15} /></button>}
  </div>;
}
function Empty({ title, description, action, small = false }: { title: string; description: string; action?: ReactNode; small?: boolean }) { return <div className={ui.cx('empty-state text-center [&_button]:text-14', small ? 'px-4.5 py-6.25 max-sm:p-4.5' : 'px-6 py-11')}><span className={ui.cx('mb-4 inline-flex items-center justify-center bg-[#f1f5e9] text-[#667254]', small ? 'size-11.25 rounded-xl' : 'size-15 rounded-[18px]')}><Leaf size={28} /></span><h3 className={ui.emptyTitle}>{title}</h3><p className={ui.cx(ui.emptyText, small && 'text-[.78rem]!')}>{description}</p>{action}</div>; }
function ProjectCard({ project, tasks, onOpen }: { project: Project; tasks: Task[]; onOpen: () => void }) {
  const completed = tasks.filter(t => t.status === 'done').length;
  const inProgress = tasks.filter(t => t.status === 'doing').length;
  const notStarted = tasks.filter(t => t.status === 'todo').length;
  const readyToClose = tasks.length > 0 && completed === tasks.length;
  return <button className="project-card min-w-0 rounded-xl border border-line bg-white px-5.5 py-5 text-left transition-[border-color,box-shadow] duration-150 hover:border-[#b6c7a4] hover:shadow-[0_5px_18px_#31452107] max-lg:p-4.5 max-xs:p-5.5" onClick={onOpen}>
    <div className="flex items-center justify-between gap-3"><span className="inline-flex size-9.5 shrink-0 items-center justify-center rounded-[9px]" style={{ color: project.color, background: `${project.color}15` }}><Folder size={21} /></span><Badge kind={project.archived ? 'neutral' : readyToClose ? 'done' : 'doing'}>{project.archived ? readyToClose ? 'ปิดแล้ว' : 'เก็บเข้าคลัง' : readyToClose ? 'พร้อมปิดโปรเจ็ค' : 'กำลังดำเนินการ'}</Badge></div>
    <h3 className="mt-4.5 truncate text-[.96rem] text-[#5b6b50] max-sm:text-14">{project.name}</h3><p className="mt-1.25 mb-5 line-clamp-2 min-h-10 text-12 leading-[1.8] text-[#6a7061]">{project.description || 'ยังไม่มีรายละเอียดโปรเจ็ค'}</p>
    <div className="mb-2 flex items-center justify-between text-12 text-[#69715e]"><span>{tasks.length ? `${completed}/${tasks.length} งานสำเร็จ` : 'ยังไม่มีงาน'}</span><strong className="font-medium text-[#627451]">{tasks.length ? `${progress(tasks)}%` : '—'}</strong></div>
    <div className={ui.progressTrack('h-1.25')}><span className={ui.progressBar} style={{ width: `${progress(tasks)}%`, background: project.color }} /></div>
    <div className="mt-3 flex flex-wrap gap-x-3 gap-y-1.5 text-[.68rem] text-[#69715e]"><span>{inProgress} กำลังทำ</span><span>{notStarted} ยังไม่เริ่ม</span><span>{completed} เสร็จแล้ว</span></div>
    <div className="mt-3.25 flex items-center justify-between border-t border-[#f0f3e9] pt-3.25 text-[.72rem] text-[#69715f]"><span className="flex items-center gap-1.5"><CalendarDays size={14} /> ส่ง {dateLabel(project.due)}</span><ArrowRight size={17} className="text-[#6a7061]" /></div>
  </button>;
}

function Dashboard({ data, user, go, onOpen, onEdit, onStatus }: { data: Data; user: DemoUser; go: (p: Page) => void; onOpen: (p: Project) => void; onEdit: (t: Task) => void; onStatus: (t: Task, s: Status) => void }) {
  const active = data.projects.filter(p => !p.archived); const tasks = data.tasks.filter(t => active.some(p => p.id === t.projectId)); const day = today(); const todays = tasks.filter(t => (datePart(t.start) === day || datePart(t.due) === day) && t.status !== 'done'); const late = tasks.filter(overdue); const upcoming = tasks.filter(t => t.status !== 'done' && !!t.due && !overdue(t)).sort((a, b) => a.due.localeCompare(b.due)).slice(0, 4);
  return <>
    <PageHeading eyebrow="LET’S MAKE TODAY COUNT" title={<>สวัสดี, {user.name.split(' ')[0]} <span className="ml-1.75 text-[1.95rem] font-normal text-[#7b6f3a]">☀</span></>} description="วันนี้มีอะไรให้เดินหน้าบ้าง? เริ่มจากแผนเล็ก ๆ ของคุณ"><button className={ui.headingBtn('primary')} onClick={() => go('create')}><Plus size={17} /> สร้างโปรเจ็ค</button></PageHeading>
    <div className="mb-6 flex items-center justify-between gap-4.5 rounded-[11px] border border-[#e2e9d6] bg-[#edf3e4] px-5.5 py-4.5 max-sm:p-4 max-xs:flex-wrap max-xs:gap-2"><div className="flex items-center gap-4 max-xs:gap-2.5"><span className="grid size-10.75 place-items-center rounded-[11px] bg-[#e4edcf] text-[#65734e] max-xs:size-9.5"><Leaf size={25} /></span><div><strong className="text-15 font-medium text-[#58723f]">{todays.length ? `วันนี้มี ${todays.length} งานรอคุณอยู่` : 'วันนี้มีพื้นที่ให้แผนใหม่ ๆ'}</strong><p className="mt-0.5 text-13 text-[#68715a] max-sm:text-11">{late.length ? `มี ${late.length} งานเลยกำหนด ลองจัดเวลาให้ใหม่แล้วค่อยไปต่อ` : 'จัดเวลาให้สิ่งสำคัญ แล้วเดินหน้าในจังหวะของคุณ'}</p></div></div><button className="flex items-center gap-2.5 text-13 whitespace-nowrap text-[#728e55] max-sm:gap-1.25 max-sm:text-12 max-xs:ml-13" onClick={() => go('calendar')}>ดูแผนบนปฏิทิน <ArrowRight size={17} /></button></div>
    <div className={ui.statsGrid()}><Stat label="โปรเจ็คที่กำลังทำ" value={active.length} icon={<FolderOpen />} note="ทุกแผนในพื้นที่ของคุณ" /><Stat label="งานที่ต้องทำวันนี้" value={todays.length} icon={<ListTodo />} note="เริ่มจากงานที่สำคัญก่อน" /><Stat label="งานที่เสร็จแล้ว" value={tasks.filter(t => t.status === 'done').length} icon={<CheckCheck />} note={`${tasks.length} งานทั้งหมด · ${progress(tasks)}% สำเร็จ`} /><Stat label="งานเลยกำหนด" value={late.length} icon={<Clock3 />} note={late.length ? 'ปรับแผนแล้วเริ่มใหม่ได้เสมอ' : 'ทุกอย่างยังอยู่ในแผน'} warning={late.length > 0} /></div>
    <div className="mb-6.5 grid grid-cols-[minmax(0,1.7fr)_minmax(280px,1fr)] gap-5.75 max-lg:grid-cols-[minmax(0,1.4fr)_minmax(260px,1fr)] max-lg:gap-4.5 max-md:grid-cols-1">
      <section className={ui.panel}><div className={ui.sectionHeading()}><div><h2 className={ui.sectionTitle}>แผนวันนี้ <span className={ui.countChip}>{todays.length}</span></h2><p className={ui.sectionSub}>{dateLabel(day, true)}</p></div><button className={ui.textBtn('text-14 text-brand hover:text-[#153729] max-sm:text-12')} onClick={() => go('tasks')}>ดูงานทั้งหมด <ArrowRight size={15} /></button></div>{todays.length ? todays.map(t => <TaskRow key={t.id} task={t} project={active.find(p => p.id === t.projectId)} onEdit={onEdit} onStatus={onStatus} compact />) : <Empty title="วันนี้ยังไม่มีงานค้าง" description="ดูแผนวันถัดไป หรือเพิ่มงานใหม่ให้โปรเจ็คของคุณ" action={<button className={ui.btn('outline')} onClick={() => go('calendar')}>เปิดปฏิทิน</button>} />}</section>
      <section className={ui.panel}><div className={ui.sectionHeading()}><div><h2 className={ui.sectionTitle}>ใกล้ถึงกำหนด</h2><p className={ui.sectionSub}>สิ่งที่ควรเผื่อเวลาไว้</p></div><CalendarDays size={20} className={ui.sectionIcon} /></div>{upcoming.length ? upcoming.map(t => <button className="flex min-h-19.25 w-full items-center gap-3 border-t border-[#f0f2ec] px-5.75 py-3.5 text-left hover:bg-paper max-md:py-4" key={t.id} onClick={() => onEdit(t)}><span className="flex h-10.75 w-10 shrink-0 flex-col items-center justify-center rounded-[7px] border border-[#edf1e4] bg-[#f6f8f0] leading-[1.4] text-[#657354]"><strong className="text-16 font-medium">{Number(datePart(t.due).slice(8))}</strong><small className="text-[.62rem]">{dateLabel(t.due).split(' ').slice(1).join(' ')}</small></span><span className="min-w-0 flex-1"><strong className="block truncate text-13 font-medium text-[#68785c]">{t.title}</strong><small className="mt-1 block text-11 text-[#69705f]">{active.find(p => p.id === t.projectId)?.name}</small></span><ChevronRight size={16} className="text-[#6b7061]" /></button>) : <Empty title="ยังไม่มีกำหนดส่งถัดไป" description="งานที่มีกำหนดส่งในอนาคตจะแสดงที่นี่" />}</section>
    </div>
    <section><div className={ui.sectionHeading('pb-4.5')}><div><h2 className={ui.sectionTitle}>โปรเจ็คของคุณ</h2><p className={ui.sectionSub}>ภาพรวมของสิ่งที่คุณกำลังสร้าง</p></div><button className={ui.textBtn('text-14 text-brand hover:text-[#153729] max-sm:text-12')} onClick={() => go('projects')}>ดูทั้งหมด <ArrowRight size={15} /></button></div>{active.length ? <div className={PROJECT_GRID}>{active.slice(0, 3).map(p => <ProjectCard key={p.id} project={p} tasks={tasks.filter(t => t.projectId === p.id)} onOpen={() => onOpen(p)} />)}</div> : <Empty title="เริ่มต้นด้วยโปรเจ็คแรก" description="ตั้งเป้าหมาย แบ่งงาน และเลือกเวลาที่จะลงมือทำ" action={<button className={ui.btn('primary')} onClick={() => go('create')}><Plus size={17} /> สร้างโปรเจ็ค</button>} />}</section>
  </>;
}
function Stat({ label, value, icon, note, warning }: { label: string; value: number; icon: ReactNode; note: string; warning?: boolean }) { return <div className={ui.statCard}><div className={ui.statLabel}><span>{label}</span><span className={ui.statIcon(warning)}>{icon}</span></div><strong className={ui.statValue(warning)}>{String(value).padStart(2, '0')}</strong><small className={ui.statNote}>{note}</small></div>; }
function PageHeading({ eyebrow, title, description, extra, children }: { eyebrow: string; title: ReactNode; description: string; extra?: ReactNode; children?: ReactNode }) {
  return <div className={ui.pageHeading}><div><span className={ui.pageEyebrow}>{eyebrow}</span><h1 className={ui.pageTitle}>{title}</h1><p className={ui.pageSub}>{description}</p>{extra}</div>{children}</div>;
}

function TasksPage({ data, onEdit, onStatus, onAdd }: { data: Data; onEdit: (t: Task) => void; onStatus: (t: Task, s: Status) => void; onAdd: () => void }) {
  const [filter, setFilter] = useState('all'); const [search, setSearch] = useState(''); const [projectId, setProjectId] = useState('all'); const active = data.projects.filter(p => !p.archived); const all = data.tasks.filter(t => active.some(p => p.id === t.projectId));
  const filters = [{ id: 'all', name: 'ทั้งหมด', count: all.length }, { id: 'today', name: 'วันนี้', count: all.filter(t => t.status !== 'done' && (datePart(t.start) === today() || datePart(t.due) === today())).length }, { id: 'soon', name: 'ใกล้ส่ง', count: all.filter(dueSoon).length }, { id: 'late', name: 'เลยกำหนด', count: all.filter(overdue).length }, { id: 'todo', name: 'ยังไม่เริ่ม', count: all.filter(t => t.status === 'todo').length }, { id: 'doing', name: 'กำลังทำ', count: all.filter(t => t.status === 'doing').length }, { id: 'done', name: 'เสร็จแล้ว', count: all.filter(t => t.status === 'done').length }];
  const shown = all.filter(t => (projectId === 'all' || t.projectId === projectId) && `${t.title} ${active.find(p => p.id === t.projectId)?.name}`.toLowerCase().includes(search.toLowerCase()) && (filter === 'all' || filter === 'today' && t.status !== 'done' && (datePart(t.start) === today() || datePart(t.due) === today()) || filter === 'soon' && dueSoon(t) || filter === 'late' && overdue(t) || filter === t.status)).sort((a, b) => Number(a.status === 'done') - Number(b.status === 'done') || (a.due || '9999').localeCompare(b.due || '9999'));
  return <>
    <PageHeading eyebrow="ONE THING AT A TIME" title="To-do list" description="งานจากทุกโปรเจ็ค เรียงไว้ให้คุณเลือกเริ่มได้ง่ายขึ้น"><button className={ui.headingBtn('primary')} onClick={onAdd}><Plus size={17} /> เพิ่มงาน</button></PageHeading>
    <div className={ui.cx(ui.filterTabs, 'mb-5.25')}>{filters.map(f => <button className={ui.filterTab(filter === f.id)} key={f.id} onClick={() => setFilter(f.id)}>{f.name}<span>{f.count}</span></button>)}</div>
    <section className={ui.panel}>
      <div className="flex justify-between gap-3.75 px-5.75 py-5 max-sm:flex-wrap max-sm:p-4.25 max-xs:p-3.75"><label className={ui.searchField('max-w-[350px] max-sm:max-w-none')}><Search size={17} /><input aria-label="ค้นหางาน" placeholder="ค้นหาชื่องานหรือโปรเจ็ค..." value={search} onChange={e => setSearch(e.target.value)} /></label><label className="m-0 flex min-w-[190px] items-center gap-1.75 text-[#68715d] max-sm:w-full"><Folder size={16} /><select className="m-0 min-h-10.5 p-2.5 text-14" aria-label="กรองโปรเจ็ค" value={projectId} onChange={e => setProjectId(e.target.value)}><option value="all">ทุกโปรเจ็ค</option>{active.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label></div>
      <div className="flex justify-between border-t border-[#f0f3e9] bg-paper px-6 py-2.5 text-[.72rem] text-[#69705f]"><span>{shown.length} รายการ</span><span className="max-sm:hidden">ความสำคัญ <span className="ml-10.5 pr-9.25">กำหนดส่ง / สถานะ</span></span></div>
      {shown.length ? shown.map(t => <TaskRow key={t.id} task={t} project={active.find(p => p.id === t.projectId)} onStatus={onStatus} onEdit={onEdit} />) : <Empty title={all.length ? 'ไม่พบงานที่ตรงกับตัวกรอง' : 'ยังไม่มีงานในรายการ'} description={all.length ? 'ลองเปลี่ยนตัวกรองหรือคำค้นหา' : 'เพิ่มงานแรก แล้วกำหนดเวลาที่เหมาะกับคุณ'} action={!all.length && <button className={ui.btn('primary')} onClick={onAdd}>เพิ่มงาน</button>} />}
    </section>
  </>;
}

