  const [anchor, setAnchor] = useState(today()); const [view, setView] = useState<'month' | 'week'>('month'); const [selected, setSelected] = useState(today()); const [projectId, setProjectId] = useState('all'); const active = data.projects.filter(p => !p.archived); const tasks = data.tasks.filter(t => active.some(p => p.id === t.projectId) && (projectId === 'all' || t.projectId === projectId));
  const weekDay = (date: string) => new Date(`${date}T12:00:00+07:00`).getUTCDay();
  const first = `${anchor.slice(0, 7)}-01`; const gridStart = view === 'month' ? shiftDate(first, -(weekDay(first) + 6) % 7) : shiftDate(anchor, -(weekDay(anchor) + 6) % 7); const dates = Array.from({ length: view === 'month' ? 42 : 7 }, (_, i) => shiftDate(gridStart, i));
  const eventsOn = (day: string) => tasks.flatMap(t => { const events: { task: Task; deadline: boolean }[] = []; if (t.start && datePart(t.start) <= day && datePart(t.end || t.start) >= day) events.push({ task: t, deadline: false }); if (datePart(t.due) === day) events.push({ task: t, deadline: true }); return events; }).sort((a, b) => (a.deadline ? a.task.due : a.task.start).localeCompare(b.deadline ? b.task.due : b.task.start));
